  "questions": [
    {
      "section": "what",
      "prompt": "你一开始想数剩饭份数，后来怎么想到改成称重量的？",
      "evidence": "一开始想数「剩了几份」，自己推翻了，改成称重量——理由是「有的人剩半碗有的人剩一口」"
    },
    {
      "section": "how",
      "prompt": "访谈时你问了两个问题就卡住了，那时候你心里在想什么？"
